-- Independent Dadyoom teaching supports, not claims about the contents of official books.
-- Idempotent: update only genuinely empty published lessons; add each origin/type once.
DO $dadyoom$
DECLARE
  r RECORD;
  target_id uuid;
  target_content text;
BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"n":1,"skill":"الممنوع من الصرف مع مثال مضبوط","passage":"في «مررتُ بأحمدَ» يُجر الاسم العلم «أحمد» بالفتحة نيابة عن الكسرة لكونه ممنوعًا من الصرف في هذا الاستعمال، ما لم يضف أو تدخل عليه أل في المواضع المناسبة. لا تعني العالمية وحدها منع جميع الأسماء من الصرف.","prompt":"ما علامة جر «أحمدَ» في المثال؟","correct":"الفتحة","w1":"الكسرة الظاهرة","w2":"الياء","w3":"الألف","practice":"اكتب ثمانية أسماء ممنوعة من الصرف ومقابلات مصروفة، ووضح سبب المنع والإعراب في كل تركيب."},{"n":2,"skill":"إبدال الواو والياء تاء في الصرف","passage":"قد يحدث الإبدال عند بناء صيغة افتعل من جذر أوله واو أو ياء وفق القواعد، مثل «اتّصل» المتصلة بالجذر «وصل» حيث تتغير الواو إلى تاء ثم يقع إدغام. يتطلب فهم الإبدال الرجوع إلى الجذر والوزن لا حفظ الصورة السطحية فقط.","prompt":"ما الجذر المرتبط بالفعل «اتّصل» في المثال؟","correct":"وصل","w1":"تصل","w2":"صلل","w3":"طسل","practice":"ابحث في معجم صرفي عن ثلاثة أفعال طرأ فيها هذا الإبدال، ثم بين الجذر والصيغة الناتجة."},{"n":3,"skill":"إبدال تاء الافتعال طاء","passage":"في الفعل «اصطبر» من «صبر» على صيغة افتعل أبدلت تاء الافتعال طاء لمجاورتها الصاد في هذا البناء. يساعد النطق والحروف المحيطة على تفسير بعض التغيرات الصرفية، ولا يطبق الحكم خارج شروطه.","prompt":"ما الحرف الذي حلت محله الطاء في «اصطبر»؟","correct":"تاء الافتعال","w1":"صاد الجذر","w2":"باء الجذر","w3":"الراء","practice":"هات ثلاثة أمثلة موثقة لإبدال تاء الافتعال طاء، مع تحديد الحرف الذي أثّر في الإبدال."},{"n":4,"skill":"إبدال تاء الافتعال دالًا","passage":"في «ازدجر» من «زجر» على صيغة افتعل طرأ إبدال لتاء الافتعال دالًا بعد الزاي في الصيغة. للمقارنة يُبحث عن أمثلة أخرى من أبواب الإبدال الموثقة في المعاجم حتى لا تعمم قاعدة خاصة.","prompt":"ما الحرف الأصلي الذي أبدل دالًا في «ازدجر»؟","correct":"تاء الافتعال","w1":"الزاي","w2":"الجيم","w3":"الراء","practice":"زن الفعلين ازدجر واصطبر، وفسر اختلاف الإبدال من حيث الأصوات المجاورة."},{"n":5,"skill":"الإيجاز والإطناب والمساواة","passage":"الإيجاز أداء المعنى بألفاظ قليلة وافيه، والإطناب زيادة لفظية لفائدة معتبرة، والمساواة مناسبة الألفاظ لمقدار المعنى دون حذف مخل أو زيادة مقصودة. في «أنجز المهمة بدقة ثم راجعها قبل التسليم» قد تؤدي الزيادة الأخيرة وظيفة تنبيهية واضحة.","prompt":"أي نوع بلاغي يشترط أن تؤدي الزيادة فائدة؟","correct":"الإطناب","w1":"الطباق","w2":"الجناس","w3":"الاستفهام","practice":"أعد صياغة فكرة في ثلاثة أساليب: موجز ومساو ومطنب لفائدة، واشرح أثر كل صياغة."},{"n":6,"skill":"حالات إعراب المضارع","passage":"«يسعى الطالبُ للعلم» مضارع مرفوع بضمة مقدرة على الألف للتعذر، و«لن يسعى» منصوب بفتحة مقدرة على الألف، و«لم يسعَ» مجزوم بحذف حرف العلة. تختلف العلامات باختلاف نهاية الفعل والأداة.","prompt":"ما علامة جزم «يسعَ» في «لم يسعَ»؟","correct":"حذف حرف العلة","w1":"السكون الظاهر","w2":"الضمة","w3":"الكسرة","practice":"اكتب خمس جمل لأفعال صحيحة ومعتلة في حالات الرفع والنصب والجزم، ثم بين العلامة."},{"n":7,"skill":"الإعلال بالنقل وخطوات التحليل","passage":"الإعلال بالنقل انتقال حركة حرف العلة إلى حرف صحيح ساكن قبله في أبنية محددة، ويحتاج بيان الصيغة المفترضة والجذر قبل الحكم. يوضح فعل مثل «يقول» بعض أحكام حروف العلة عند المقارنة بأصولها الصرفية في المراجع.","prompt":"ما جوهر الإعلال بالنقل؟","correct":"انتقال الحركة من حرف علة إلى صحيح قبله","w1":"حذف كل حروف الجذر","w2":"إضافة ياء النسب","w3":"تكرار الهمزة","practice":"استعن بمرجع صرفي معتمد لتحليل ثلاثة أفعال فيها نقل حركة، واذكر الصيغة قبل التغيير وبعده."},{"n":8,"skill":"الإعلال بالحذف في الفعل المعتل","passage":"«قُلْ» فعل أمر من «قال يقول»، ويظهر فيه حذف حرف العلة في الصيغة وفق قواعد الاشتقاق. لا تكفي مقارنة عدد الحروف وحده للحكم؛ ينبغي معرفة الجذر وباب الفعل والمرحلة الصرفية.","prompt":"أي ظاهرة تظهر في صياغة «قُلْ» من «قال»؟","correct":"حذف حرف العلة","w1":"إضافة ألف بعد اللام","w2":"إبدال القاف","w3":"تثنية الفعل","practice":"حلل أربعة أفعال أمر معتلة الجذور مبينًا ما حُذف أو تغير في الصيغة."},{"n":9,"skill":"الطباق الإيجابي والسلبي","passage":"«الليل والنهار» لفظان متضادان يمكن أن يشكلا طباق إيجاب، وقد يظهر طباق السلب بجمع إثبات الفعل ونفيه في سياق واحد مناسب. لا يُعد اختلاف كلمتين في المعنى تضادًا إذا لم تكن العلاقة ضدية.","prompt":"أي زوج يوضح الطباق الإيجابي؟","correct":"الليل والنهار","w1":"الليل والظلام","w2":"القراءة والكتاب","w3":"السوق والبيت","practice":"أنشئ ثلاث جمل لطباق الإيجاب والسلب، ووضح كيف يخدم التضاد الفكرة."},{"n":10,"skill":"المقابلة بين المعاني","passage":"المقابلة البلاغية ترتيب معنيين أو أكثر ثم ما يقابلها في الاتجاه المضاد وفق بناء لفظي مقصود. تدريب مستقل: «يصدق الكريم في وعده فيطمئن صديقه، ويكذب البخيل في عهده فيقلق من حوله». يقارن المثال صفات ونتائج في سياق إنشائي.","prompt":"ما أساس المقابلة في المثال؟","correct":"ترتيب معان ثم ما يقابلها","w1":"تكرار الكلمة نفسها","w2":"ذكر عدد فقط","w3":"غياب التضاد","practice":"اكتب فقرة قصيرة توظف مقابلة واضحة بين معنيين ونتيجتين، ثم فسر أثر ترتيب الأزواج."},{"n":11,"skill":"العدد والمعدود واتفاقهما","passage":"«ثلاثةُ كتبٍ» تركيب لعدد من ثلاثة إلى عشرة يخالف فيه العدد المعدود في التذكير والتأنيث، و«ثلاثُ صفحاتٍ» للمعدود المؤنث. أما الواحد والاثنان والأعداد المركبة فلها أحكام مختلفة تحتاج تطبيقًا منفصلًا.","prompt":"أي تركيب صحيح لثلاثة كتب؟","correct":"ثلاثة كتب","w1":"ثلاث كتب","w2":"ثالث كتب","w3":"ثلاثة كتابًا","practice":"اكتب أعدادًا من واحد إلى عشرين مع معدود مذكر ومؤنث، ثم اضبط الصيغ في جمل."},{"n":12,"skill":"الإدغام بين الحروف المتماثلة","passage":"في «مدَّ» تظهر دال مشددة ناتجة في التحليل الصرفي عن التقاء دالين متماثلتين من جذر «مدد» وفق القاعدة. للإدغام أحوال واجبة وجائزة تتوقف على البنية والتصريف، ولا يحدد نوعه بمجرد وجود شدة.","prompt":"ما الجذر الثلاثي للفعل «مدَّ»؟","correct":"مدد","w1":"ميد","w2":"ماد","w3":"ددد","practice":"ابحث عن خمسة أفعال مدغمة، واكتب الأصل وموضع الإدغام وأحكامه بالرجوع إلى مرجع صرفي."},{"n":13,"skill":"التورية بين المعنى القريب والبعيد","passage":"في التورية لفظ يحتمل معنيين أحدهما قريب يتبادر إلى الذهن والآخر أبعد يُراد بدليل السياق. كلمة «عين» قد تعني عضو الإبصار أو نبع الماء؛ لا تكون تورية في كل جملة بل تحتاج قصدًا بلاغيًا وسياقًا ينصرف فيه المعنى.","prompt":"ما الشرط الذي يميز التورية عن تعدد المعاني العادي؟","correct":"قصد معنى بعيد مع إيهام معنى قريب","w1":"وجود مرادفين","w2":"تكرار حرف","w3":"ذكر اسم علم","practice":"أنشئ مثالين لتورية مع شرح المعنى القريب والبعيد والقرينة دون اقتباسات منسوبة إلى مؤلفين."},{"n":14,"skill":"تأكيد المدح بما يشبه الذم وعكسه","passage":"في «لا عيب في عمله إلا أنه بالغُ الأمانة» يأتي بعد أداة الاستثناء وصف محمود خلاف المتوقع بعد ذكر العيب، فيؤكد المدح بما يشبه الذم. ينبغي التمييز بين هذا الأسلوب وبين السخرية أو الذم الحقيقي في السياق.","prompt":"ما الأثر في «لا عيب فيه إلا أنه كريم»؟","correct":"تأكيد المدح بتوقع ذم ثم إيراد مدح","w1":"تأكيد ذم صريح","w2":"وصف محايد","w3":"استفهام","practice":"اكتب مثالين لتأكيد المدح بما يشبه الذم، ومثالًا لعكسه، ثم وضح موضع المفارقة."}]'::jsonb) AS x(
    n integer,skill text,passage text,prompt text,correct text,w1 text,w2 text,w3 text,practice text
  ) LOOP
    SELECT l.id,l.content INTO STRICT target_id,target_content
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=12
    JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027' AND cu.id='79a8732d-6a86-46cd-8cad-31673af20a0c'
    JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
    WHERE u.title='نحو 312 — شرح ابن عقيل والصرف الميسر ج3 ومفتاح البلاغة' AND u.semester=2 AND l.sort_order=r.n AND l.status='published'
    FOR UPDATE OF l;
    IF char_length(coalesce(target_content,''))<350 THEN
      UPDATE public.lessons SET
        content='ضاديوم — إثراء مستقل أصلي للصف الثامن، الفصل الثاني. لا يمثل النص الوزاري الأصلي ولا يثبت مطابقة العنوان للمصدر.'||E'\n\n'||
          'المهارة: '||r.skill||E'\n\n'||
          'النموذج التعليمي والشرح: '||r.passage||E'\n\n'||
          'أهداف التعلم: يحدد المتعلم شاهدًا صحيحًا ويشرح دلالته، ويميّز بين الفكرة والدليل، ثم ينتج كتابة مناسبة للمهارة.'||E'\n\n'||
          'سؤال الفهم: '||r.prompt||E'\n\n'||
          'التطبيق الكتابي: '||r.practice||E'\n\n'||
          'التمايز: المبتدئ يحصل على كلمات مفتاحية وبداية جملة؛ المتوسط يجيب بدليل مستقل؛ المتقدم يقارن بين صياغتين ويبرر تحسيناته.'||E'\n\n'||
          'مراجعة المعلم: تحقق من صحة الاستدلال والإملاء وعلامات الترقيم والترابط. لا تُمنح درجة جودة تلقائية لمجرد تسليم المهمة.'||E'\n\n'||
          'تنبيه المصدر: راجع العنوان المستورد والكتاب الرسمي قبل وصف هذا التدريب بأنه مطابق للمنهج.'||E'\n\n'||'المدخل السابق المحفوظ: '||coalesce(target_content,''),
        updated_at=now()
      WHERE id=target_id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.lessons WHERE id=target_id AND content LIKE 'ضاديوم — إثراء مستقل أصلي للصف الثامن%') THEN
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'فهم النص الإثرائي','multiple_choice','assessment',r.prompt,
        jsonb_build_object('origin','DADYOOM_BH_RELIGIOUS_G12_T2_NAHW312_ORIGINAL_20261008','notOfficialBook',true,'ocrReview','pending','options',CASE (r.n % 4) WHEN 0 THEN jsonb_build_array(r.correct,r.w1,r.w2,r.w3) WHEN 1 THEN jsonb_build_array(r.w1,r.correct,r.w2,r.w3) WHEN 2 THEN jsonb_build_array(r.w1,r.w2,r.correct,r.w3) ELSE jsonb_build_array(r.w1,r.w2,r.w3,r.correct) END),
        jsonb_build_object('correct',r.correct),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='multiple_choice' AND content->>'origin'='DADYOOM_BH_RELIGIOUS_G12_T2_NAHW312_ORIGINAL_20261008');
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'كتابة تطبيقية بمراجعة المعلم','writing','practice',r.practice,
        jsonb_build_object('origin','DADYOOM_BH_RELIGIOUS_G12_T2_NAHW312_ORIGINAL_20261008','notOfficialBook',true,'humanReviewRequired',true,'text',r.practice,'skillQualityAutoVerified',false),
        jsonb_build_object('grading_mode','completion_only_reference','model_answer','لا تكفي المطابقة النصية؛ يصحح المعلم ملاءمة الأفكار والدليل والترابط.'),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='writing' AND content->>'origin'='DADYOOM_BH_RELIGIOUS_G12_T2_NAHW312_ORIGINAL_20261008');
    END IF;
  END LOOP;
END
$dadyoom$;